// Go has no inline keyword. The inliner uses an AST-node cost budget (~80 by
// default); functions over it are not inlined. Small functions chain fine:
func Sum(xs []int) int {
    s := 0
    for _, x := range xs { s += x }      // inlined into the caller
    return s
}
// check what was inlined:
//   go build -gcflags='-m' ./...    // "can inline Sum" / "cannot inline Big: function too complex"

// interfaces defeat inlining (the dynamic type is unknown), which is why
